SELECT setval(pg_get_serial_sequence('users', 'id'), (SELECT COALESCE(MAX(id), 0) + 1 FROM users));

SELECT setval(pg_get_serial_sequence('profiles', 'id'), (SELECT COALESCE(MAX(id), 0) + 1 FROM profiles));

SELECT setval(pg_get_serial_sequence('genres', 'id'), (SELECT COALESCE(MAX(id), 0) + 1 FROM genres));

SELECT setval(pg_get_serial_sequence('title_genres', 'id'), (SELECT COALESCE(MAX(id), 0) + 1 FROM title_genres));

SELECT setval(pg_get_serial_sequence('my_list', 'id'), (SELECT COALESCE(MAX(id), 0) + 1 FROM my_list));

SELECT setval(pg_get_serial_sequence('ratings', 'id'), (SELECT COALESCE(MAX(id), 0) + 1 FROM ratings));

SELECT setval(pg_get_serial_sequence('continue_watching', 'id'), (SELECT COALESCE(MAX(id), 0) + 1 FROM continue_watching));

SELECT setval(pg_get_serial_sequence('episodes', 'id'), (SELECT COALESCE(MAX(id), 0) + 1 FROM episodes));
